import * as C from './ledger-gauge-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const own=(x,k)=>x!==null&&typeof x==='object'&&Object.hasOwn(x,k),get=(x,k,f='')=>own(x,k)?x[k]:f,list=x=>Array.isArray(x)?x:[];
const btn=(attrs,text)=>`<button type="button" class="secondary" ${attrs}>${esc(text)}</button>`,p=text=>`<p>${esc(text)}</p>`;
const retained=label=>`<p class="ledger-retained" data-ledger-unreadable>${esc(label)} cannot be read here. Its exact saved form stays in your notebook download.</p>`;
const helpButton=(w,id,label)=>own(w.source.help,id)?btn(`data-ledger-help="${esc(id)}"`,label||w.source.help[id].title):'';
function helpers(w,ids){return ids.filter((id,i,a)=>a.indexOf(id)===i&&w.help.includes(id)&&own(w.source.help,id)).map(id=>`<section class="ledger-help">${p(w.source.help[id].title)}${p(w.source.help[id].text)}</section>`).join('');}
function chooser(items,current,attr,label,text=x=>x.title||x.prompt||x.text){const at=items.findIndex(x=>x.id===current);return `<nav class="ledger-chooser" aria-label="${esc(label)}"><label>${esc(label)}<select data-ledger-${attr}><option value="" disabled${at<0?' selected':''}>Choose</option>${items.map(x=>`<option value="${esc(x.id)}"${x.id===current?' selected':''}>${esc(text(x))}</option>`).join('')}</select></label><div class="ledger-actions">${at>0?btn(`data-ledger-${attr}-go="${esc(items[at-1].id)}"`,'Previous'):''}${at>=0&&at<items.length-1?btn(`data-ledger-${attr}-go="${esc(items[at+1].id)}"`,'Next'):''}</div></nav>`;}
function model(w){const m=w.source.model;if(!C.validLedgerModel(m))return own(w.source,'model')?retained('Earlier supplied model'):'';const stage=m.stages.find(s=>s.id===w.modelStage);if(!stage)return retained('Earlier model stage');const total=stage.counts.reduce((a,b)=>a+b,0);return `<section class="ledger-model"><h3>${esc(m.title)}</h3>${p(stage.text)}<div class="ledger-stacks" role="img" aria-label="${esc(stage.counts.map(n=>`${n} blocks, ${n*m.unitValue} ${m.unit}`).join('; '))}">${stage.counts.map(n=>`<div><div class="ledger-stack">${Array.from({length:n},()=>'<span></span>').join('')}</div><p>${n} × ${m.unitValue} ${esc(m.unit)} = ${n*m.unitValue} ${esc(m.unit)}</p></div>`).join('')}</div>${p(`${total} blocks total · ${stage.counts.length} stacks`)}${p(m.limit)}<div class="ledger-actions">${btn(`data-ledger-model="next"${stage===m.stages.at(-1)?' disabled':''}`,'Next move')}${btn('data-ledger-model="reset"','Start this example again')}</div></section>`;}
function teaching(w,page){const l=get(w.learn,page.id,null);if(!C.validLedgerLearn(l,page))return retained('Earlier learning card');const target=page.guidedFor,eligible=!target||target.kind==='task'&&get(w.tasks,page.id)===target.id||target.kind==='claim'&&w.claimId===target.id||target.kind==='part'&&w.partId===target.id;return `<section class="ledger-learning"><h3>Look together</h3>${l.folded?'<p>Learning card folded. Earlier support remains kept.</p>':page.learn.slice(0,l.count).map(x=>p(x.text)).join('')+(l.guided&&eligible?page.guided.map(x=>p(x.text)).join(''):'')+(page.role==='records'?model(w):'')}<div class="ledger-actions">${l.folded?btn(`data-ledger-fold="false"`,'Open learning card'):btn('data-ledger-fold="true"','Fold learning card')}${!l.folded&&l.count<page.learn.length?btn('data-ledger-learn="next"','Next teaching line'):''}${btn('data-ledger-learn="question"','I know this, show the question')}${page.guided.length&&eligible?btn('data-ledger-learn="guided"','Show me how'):''}</div></section>`;}
function ledgerPlot(w){const s=w.source,r=s.records,max=Math.max(1,...r.events.map(e=>e.height)),top=Math.ceil(max/20)*20,x=y=>60+(y-r.firstYear)/(r.lastYear-r.firstYear||1)*570,y=h=>260-h/top*210;return `<figure class="ledger-plot"><svg viewBox="0 0 680 330" role="img" aria-label="${esc(s.labels.height)}; ${esc(s.labels.year)} ${r.firstYear}–${r.lastYear}"><title>${esc(s.labels.height)}</title>${Array.from({length:5},(_,i)=>{const n=top*i/4;return `<line x1="60" x2="645" y1="${y(n)}" y2="${y(n)}" class="ledger-grid"/><text x="50" y="${y(n)+5}" text-anchor="end">${n}</text>`;}).join('')}<line x1="60" x2="645" y1="260" y2="260"/><line x1="60" x2="60" y1="50" y2="260"/><line class="ledger-change" x1="${x(r.changeYear)}" x2="${x(r.changeYear)}" y1="35" y2="260"/><text x="${x(r.changeYear)}" y="20" text-anchor="middle">${r.changeYear} · both changes</text>${r.events.map(e=>`<rect class="ledger-bar" data-ledger-event="${esc(e.id)}" x="${x(e.year)-4}" y="${y(e.height)}" width="8" height="${260-y(e.height)}"/><text x="${x(e.year)}" y="${y(e.height)-7}" text-anchor="middle">${e.height}</text><text x="${x(e.year)}" y="282" text-anchor="middle">${e.year}</text>`).join('')}<text x="350" y="316" text-anchor="middle">${esc(s.labels.year)} (${r.firstYear}–${r.lastYear})</text><text x="65" y="43">${esc(s.units.cm)}</text></svg><figcaption>${esc(r.changeText)}. ${esc(r.limit)}</figcaption></figure>${btn(`data-ledger-storm="${!w.showStorm}" aria-pressed="${w.showStorm}"`,w.showStorm?'Hide separate later storm':'Show separate later storm')}${w.showStorm?`<aside class="ledger-storm">${p(r.storm.label)}<div class="ledger-storm-mark" role="img" aria-label="${esc(r.storm.label)}"></div>${p(r.storm.limit)}</aside>`:''}<div class="ledger-table-wrap"><table><caption>${esc(s.labels.ordinary)}</caption><thead><tr><th>${esc(s.labels.year)}</th><th>${esc(s.labels.height)}</th></tr></thead><tbody>${r.events.map(e=>`<tr><td>${e.year}</td><td>${e.height} ${esc(s.units.cm)}</td></tr>`).join('')}</tbody></table></div>${p(r.selectionNote)}${p(r.limit)}`;}
function rainTable(w){const s=w.source,a=C.summarizeLedger(s);return `<div class="ledger-table-wrap"><table><caption>Copied rain tally beside selected flood entries</caption><thead><tr><th>${esc(s.labels.year)}</th><th>Recorded big-rain events</th><th>${esc(s.labels.entries)}</th><th>${esc(s.labels.height)} · maximum</th></tr></thead><tbody>${a.intervals.map(i=>`<tr><th>${esc(i.label)}</th><td>${i.rainCount}</td><td>${i.count}</td><td>${i.max===null?esc(s.labels.unavailable):`${i.max} ${esc(s.units.cm)}`}</td></tr>`).join('')}</tbody></table></div>${p(s.records.limit)}`;}
function supportDetails(record){return own(record,'priorSupport')?'<details><summary>Earlier teaching and help</summary><p>Earlier teaching and help requests remain with the visit where you used them.</p></details>':'';}
function originalAnswer(c){const t=c.source.task;if(c.kind==='choice'){const choice=t.choices.find(x=>x.id===c.raw.choiceId);return choice?p(choice.text):retained('Original supplied choice');}return t.fields.map(f=>{const value=c.raw.none.includes(f.id)?'Not available from these records':get(c.raw.fields,f.id);return `<p><strong>${esc(f.label)} (${esc(get(c.source.units,f.unit,f.unit))}):</strong> <span>${esc(value)}</span></p>`;}).join('');}
function response(c,label){return C.validLedgerCheck(c)?`<section class="ledger-feedback"><h4>${esc(label)}</h4><p>Supported practice · original response</p><h4>${esc(c.source.task.prompt)}</h4>${p(c.source.task.context)}${originalAnswer(c)}${p(c.feedback)}${supportDetails(c)}</section>`:retained(label);}

function task(w,page){const tasks=w.source.tasks.filter(t=>t.pageId===page.id),t=tasks.find(t=>t.id===get(w.tasks,page.id));if(!t)return tasks.length?retained('Current question'):'';const raw=get(w.answers,t.id,null),valid=!own(w.answers,t.id)||C.validLedgerAnswer(raw,t),d=valid&&raw?raw:{fields:{},none:[],choiceId:''},latest=w.checks.filter(c=>c&&typeof c==='object'&&own(c,'taskId')&&c.taskId===t.id).at(-1);return chooser(tasks,t.id,'task','Question')+`<section class="ledger-task"><h3 id="ledger-question" tabindex="-1">${esc(t.prompt)}</h3>${p(t.context)}${!valid?retained('Earlier answer'):''}<fieldset${!valid?' disabled':''}><legend>Your response</legend>${t.kind==='numeric'?t.fields.map(f=>`<label for="ledger-field-${esc(f.id)}">${esc(f.label)} (${esc(get(w.source.units,f.unit,f.unit))})<input id="ledger-field-${esc(f.id)}" data-ledger-field="${esc(f.id)}" data-task="${esc(t.id)}" data-ledger-draft inputmode="decimal" maxlength="40" value="${esc(get(d.fields,f.id))}"${d.none.includes(f.id)?' disabled':''}></label><label class="ledger-none"><input type="checkbox" data-ledger-none="${esc(f.id)}" data-task="${esc(t.id)}"${d.none.includes(f.id)?' checked':''}>${esc(w.source.labels.unavailable)}</label>`).join(''):`<label>Choose a sentence<select data-ledger-answer="${esc(t.id)}"><option value="">Leave open</option>${t.choices.map(c=>`<option value="${esc(c.id)}"${c.id===d.choiceId?' selected':''}>${esc(c.text)}</option>`).join('')}</select></label>`}</fieldset><div class="ledger-actions">${valid?btn(`data-ledger-check="${esc(t.id)}"`,'Check this response'):''}${helpButton(w,t.hintId,'Hint')}${helpButton(w,t.exampleId,'Different example')}${btn(`data-ledger-skip="${esc(t.id)}"`,'Leave this question open')}</div>${helpers(w,[t.hintId,t.exampleId,t.skipId])}<section id="ledger-result" tabindex="-1">${latest!==undefined?response(latest,'Latest response'):''}${own(w.firstChecks,t.id)?response(w.firstChecks[t.id],'First response'):''}</section></section>`;}
function claims(w){const s=w.source,c=s.claims.find(c=>c.id===w.claimId);if(!c)return retained('Current claim');const selected=get(w.claims,c.id),healthy=!own(w.claims,c.id)||s.trays.some(t=>t.id===selected),latest=w.claimHistory.filter(x=>x&&typeof x==='object'&&own(x,'cardId')&&x.cardId===c.id).at(-1);return chooser(s.claims,c.id,'claim','Claim',x=>x.text)+`<section class="ledger-claim"><h3 id="ledger-question" tabindex="-1">${esc(c.text)}</h3>${!healthy?retained('Earlier tray selection'):''}<div class="ledger-actions">${s.trays.map(t=>btn(`data-ledger-tray="${esc(t.id)}" data-card="${esc(c.id)}" aria-pressed="${selected===t.id}"${!healthy?' disabled':''}`,t.label)).join('')}</div>${latest!==undefined?(C.validLedgerClaim(latest)?`<section class="ledger-feedback">${p(latest.reply)}<p>Original tray reply · no score</p>${supportDetails(latest)}</section>`:retained('Latest tray reply')):''}${helpButton(w,c.hintId,'Hint')}${helpButton(w,c.exampleId,'Different example')}${helpButton(w,'claim-skip','Help leaving this open')}${helpers(w,[c.hintId,c.exampleId,'claim-skip'])}<details data-ledger-panel="claim-history"><summary>Earlier selections for this claim</summary>${w.claimHistory.filter(x=>x&&typeof x==='object'&&x.cardId===c.id).map(x=>C.validLedgerClaim(x)?p(x.reply)+supportDetails(x):retained('Earlier reply')).join('')}</details></section>`;}
function compactResponse(r,label){if(!r||typeof r!=='object'||typeof r.feedback!=='string')return retained(label);return `<h5>${esc(label)}</h5>${r.context?p(r.context.prompt)+p(r.context.context):''}${p(r.feedback)}`;}
function keepCard(k,label){if(!C.validLedgerKeep(k))return retained(label);return `<article class="ledger-kept"><h3>${esc(label)}</h3>${keptPlan(k)}${k.renderedParts.map(x=>`<section><h4>${esc(x.title)}</h4>${x.unreadable?retained('Earlier writing'):p(x.text||'Left open')}<p class="ledger-caption">${x.mode==='supplied'?'Supplied words':'My writing draft'}${x.starterUsed===true?' · Supplied starter used earlier':''}</p></section>`).join('')}<details data-ledger-panel="read-${esc(label)}"><summary>Read your page</summary>${keptPlan(k)}${k.renderedParts.map(x=>`<h4>${esc(x.title)}</h4>${p(x.text||'Left open')}`).join('')}${p(k.closing)}</details><section><h4>Responses kept with this page</h4>${k.responses.map(r=>r&&typeof r==='object'?`<div class="ledger-kept-response">${r.latestUnreadable?retained('Latest response'):r.latest?compactResponse(r.latest,'Latest response'):''}${r.first?compactResponse(r.first,'First response'):''}</div>`:retained('Earlier response summary')).join('')}${k.claims.map(c=>c&&typeof c.reply==='string'?p(c.reply):retained('Earlier claim summary')).join('')}</section></article>`;}
function noteEditor(w,revisionAction=''){const s=w.source,part=s.parts.find(p=>p.id===w.partId);if(!part)return retained('Current writing part');const raw=get(w.writing,part.id,null),valid=!own(w.writing,part.id)||(C.validLedgerPart(raw)&&(raw.choiceId===''||part.options.some(x=>x.id===raw.choiceId))),d=valid&&raw?raw:{mode:'own',own:'',choiceId:''},selected=part.options.find(o=>o.id===d.choiceId),plan=s.plans.find(p=>p.id===w.planId),mismatch=selected?.planId&&selected.planId!==w.planId,options=part.options.filter(x=>!x.planId||x.planId===w.planId||x.id===d.choiceId);return `<label>Provisional plan<select data-ledger-plan><option value="">Leave open for now</option>${s.plans.map(p=>`<option value="${esc(p.id)}"${p.id===w.planId?' selected':''}>${esc(p.title)}</option>`).join('')}</select></label>${plan?p(plan.text):''}<p>Changing the provisional plan leaves your writing and supplied choices in place.</p>`+chooser(s.parts,part.id,'part','Writing part')+`<section class="ledger-writing"><h3 id="ledger-question" tabindex="-1">${esc(part.title)}</h3>${p(part.prompt)}${!w.planId&&part.openHelp?p(part.openHelp):''}${!valid?retained('Earlier writing draft'):''}<fieldset${!valid?' disabled':''}><legend>Both versions stay available</legend><div class="ledger-actions">${['own','supplied'].map(mode=>btn(`data-ledger-mode="${mode}" data-part="${esc(part.id)}" aria-pressed="${d.mode===mode}"`,mode==='own'?'My writing draft':'Supplied words')).join('')}</div><label>Choose supplied words<select data-ledger-writing-choice="${esc(part.id)}"><option value="">Leave open</option>${options.map(x=>`<option value="${esc(x.id)}"${x.id===d.choiceId?' selected':''}>${esc(x.label)}${x.planId&&x.planId!==w.planId?` · earlier plan: ${esc(s.plans.find(p=>p.id===x.planId)?.title||x.planId)}`:''}</option>`).join('')}</select></label>${selected?`<blockquote>${esc(selected.text)}</blockquote>`:d.choiceId?retained('Earlier supplied choice'):''}${mismatch?'<p class="ledger-retained">These supplied words name an earlier plan. Your current plan and both drafts are kept separately; revise either when you wish.</p>':''}${btn(`data-ledger-starter="${esc(part.id)}"${!selected?' disabled':''}`,'Use as a starting draft')}${d.starterUsed===true?'<p data-ledger-starter-used>Supplied starter used earlier.</p>':''}<label for="ledger-own-${esc(part.id)}">Your writing draft<textarea id="ledger-own-${esc(part.id)}" data-ledger-own="${esc(part.id)}" data-ledger-draft rows="5" maxlength="1600">\n${esc(d.own)}</textarea></label><p>${d.mode==='supplied'?'Supplied words':'My writing draft'} will appear in your kept page. Both versions stay available.</p></fieldset>${helpButton(w,part.helpId,'Writing help')}${helpers(w,[part.helpId])}</section>${revisionAction}${btn('data-ledger-keep','Keep my case note')}<section id="ledger-note-result" tabindex="-1">${own(w,'kept')?keepCard(w.kept,'Latest case note'):''}${own(w,'firstKept')?keepCard(w.firstKept,'First case note'):''}</section>${s.connections.map(c=>`<details><summary>${esc(c.title)}</summary>${p(c.text)}<a href="${esc(c.href)}">${esc(c.title)}</a></details>`).join('')}`;}
// Local panels belong to this notebook and visit, not to a saved learner level.
const revisionLocal=(state,w)=>C.ledgerRevisionPresentation(state);
function revisionParts(r,afterReadable){const parts=[...r.before.source.parts,...(afterReadable?r.after.source.parts:[])];return parts.filter((x,i)=>parts.findIndex(p=>p.id===x.id)===i);}
function revisionPartKey(r,v,afterReadable){const parts=revisionParts(r,afterReadable);return parts.some(p=>p.id===v.part)?v.part:parts[0]?.id||'';}
function revisionPicture(k,key,label){const part=k.renderedParts.find(p=>p.id===key);return `<article class="ledger-revision-picture"><h4>${esc(label)}</h4>${keptPlan(k,'h5')}${part?`<h5>${esc(part.title)}</h5>${part.unreadable?retained('Earlier writing'):p(part.text||'Left open')}<p class="ledger-caption">${part.mode==='supplied'?'Supplied words':'My writing draft'}${part.starterUsed===true?' · Supplied starter used earlier':''}</p>`:p(k.source.parts.some(p=>p.id===key)?'No text was kept for this part.':'This part was not in this picture.')}</article>`;}
function readerQuestion(r){const c=r.source.cards.find(c=>c.id===r.currentId);return `<section class="ledger-reader-card"><h3 id="ledger-reader-heading" tabindex="-1">${esc(c.name)}</h3>${p(c.role)}<p class="ledger-reader-question">${esc(c.question)}</p>${p(c.prompt)}</section>`;}
function note(w,state){
 const view=C.revisionLedgerView(w);if(view.status==='empty')return noteEditor(w,`<aside class="ledger-revision-invitation">${p('Wren wants a note the town can question. Keep a picture of this draft, try a reader’s question, then decide what you want to change.')}${btn('data-ledger-revision-start',"Try a reader's question")}</aside>`);
 if(view.status!=='ready')return retained('Earlier reader conversation')+noteEditor(w);
 const r=view.revision,v=revisionLocal(state,w),part=revisionPartKey(r,v,view.afterReadable),nav=`<nav class="ledger-revision-tabs" aria-label="Writing views">${[['draft','My note'],['reader',"Reader's question"],['compare','Compare versions']].map(([key,label])=>btn(`data-ledger-revision-tab="${key}" aria-pressed="${v.panel===key}"`,label)).join('')}</nav>`,label=p('Questions to try, not a score for your writing.'),keep=own(r,'after')&&!view.afterReadable?retained('Latest kept revision'):btn('data-ledger-revision-keep','Keep this revision');
 let body;
 if(v.panel==='reader')body=chooser(w.source.parts,w.partId,'part','Writing part')+`<div class="ledger-readers" role="group" aria-label="Choose a reader">${r.source.cards.map(c=>btn(`data-ledger-reader="${esc(c.id)}" aria-pressed="${c.id===r.currentId}"`,`${c.name}: ${c.role}`)).join('')}</div>`+readerQuestion(r)+btn('data-ledger-revision-tab="draft"','Return to my note')+keep;
 else if(v.panel==='compare')body=`<h3 id="ledger-revision-heading" tabindex="-1">Two kept pictures of your note</h3><label>Part to compare<select data-ledger-revision-part>${revisionParts(r,view.afterReadable).map(x=>`<option value="${esc(x.id)}"${x.id===part?' selected':''}>${esc(x.title)}</option>`).join('')}</select></label><div class="ledger-revision-pictures">${revisionPicture(r.before,part,"Before the reader's question")}${view.afterReadable?revisionPicture(r.after,part,'Latest kept revision'):own(r,'after')?retained('Latest kept revision'):p('Your earlier draft is safe. Return to your note, then keep a revision whenever you want. An unfinished or unchanged note is welcome.')}</div>${p('These are kept pictures. Your working note may have changed since you kept the revision.')}${p(r.source.closing)}${btn('data-ledger-revision-tab="draft"','Return to my note')}`;
 else body=`<aside class="ledger-reader-reminder">${p(r.source.cards.find(c=>c.id===r.currentId).question)}</aside>`+noteEditor(w,keep);
 return `<section class="ledger-revision" data-ledger-revision>${nav}${label}${body}</section>`;
}
function revisionNarration(w,state){const view=C.revisionLedgerView(w);if(view.status!=='ready')return null;const r=view.revision,v=revisionLocal(state,w);if(v.panel==='draft')return null;if(v.panel==='reader'){const c=r.source.cards.find(c=>c.id===r.currentId);return ['Questions to try, not a score for your writing.','Writing part: '+(w.source.parts.find(p=>p.id===w.partId)?.title||'Left open'),c.name,c.role,c.question,c.prompt].join('\n\n');}const key=revisionPartKey(r,v,view.afterReadable),words=[];for(const [k,label]of [[r.before,"Before the reader's question"],...(view.afterReadable?[[r.after,'Latest kept revision']]:[])]){const plan=k.source.plans.find(p=>p.id===k.planId),part=k.renderedParts.find(p=>p.id===key);words.push(label,plan?plan.title+'. '+plan.text:'Provisional plan left open for now.',part?part.title:'Part not in this picture.',part?.unreadable?'Earlier writing cannot be read here.':part?.text||'Left open');}if(!view.afterReadable)words.push(own(r,'after')?'Latest kept revision cannot be read here.':'No revision picture kept yet.');words.push('These are kept pictures. Your working note may have changed since you kept the revision.',r.source.closing);return words.join('\n\n');}
function revisionHearLabel(w,state){const view=C.revisionLedgerView(w);if(view.status!=='ready')return 'Hear this page';return ({reader:'Hear this question',compare:'Hear these versions'})[revisionLocal(state,w).panel]||'Hear this page';}
function visits(v){return `<details data-ledger-panel="visits"><summary>Your visits</summary>${v.visits.map(x=>x.readable?btn(`data-ledger-resume="${esc(x.id)}" aria-pressed="${x.id===v.current}"`,x.title):retained(x.title)).join('')}${btn('data-ledger-start','Open a new visit')}</details><details data-ledger-panel="adults"><summary>Grown-ups · notebook space and records</summary><p>Fictional sources, requested support, raw answers, ungraded claims, and first/latest notes stay separate. Available teaching is not evidence it was read. Supported practice does not establish independent proficiency.</p><p>The reader questions are fixed prompts for any draft. They are not generated from or matched to your child’s writing, and no algorithm grades the prose. Revision pictures stay separate from the original case-note keeps.</p><p>Up to 8 visits, 32 checks and 48 claim selections per visit are kept; nothing is removed automatically. The shared notebook size limit can refuse changes sooner. Unreadable work stays exact in downloads.</p><a href="#notes">Open notes and download</a>${v.visits.length?`<label>Visit to remove<select data-ledger-remove-choice><option value="">Choose one visit</option>${v.visits.map(x=>`<option value="${esc(x.id)}">${esc(x.title)}${x.readable?'':' · unreadable'}</option>`).join('')}</select></label>${btn('data-ledger-remove','Remove only this visit')}`:''}</details>`;}
function sourceTables(w){const s=w.source,r=s.records;return `<section class="ledger-source-tables"><h3>Numbers in the fictional records</h3><div class="ledger-table-wrap"><table><caption>${esc(s.labels.ordinary)}</caption><thead><tr><th>${esc(s.labels.year)}</th><th>${esc(s.labels.height)}</th></tr></thead><tbody>${r.events.map(e=>`<tr><td>${e.year}</td><td>${e.height} ${esc(s.units.cm)}</td></tr>`).join('')}</tbody></table></div>${p(r.limit)}<div class="ledger-table-wrap"><table><caption>Copied big-rain event counts</caption><thead><tr><th>${esc(s.labels.year)}</th><th>Recorded big-rain events</th></tr></thead><tbody>${r.intervals.map(i=>`<tr><th>${esc(i.label)}</th><td>${i.rainCount}</td></tr>`).join('')}</tbody></table></div></section>`;}
function keptPlan(k,level='h4'){if(!k.planId)return '<p>Provisional plan: Left open for now</p>';const plan=list(k.source.plans).find(p=>p&&p.id===k.planId);return plan?`<section class="ledger-kept-plan"><${level}>Original provisional plan · ${esc(plan.title)}</${level}>${p(plan.text)}</section>`:retained('Original provisional plan');}
function checkWords(c){if(!C.validLedgerCheck(c))return [];const t=c.source.task;return [t.prompt,t.context,...(c.kind==='choice'?[t.choices.find(x=>x.id===c.raw.choiceId)?.text||''] :t.fields.map(f=>`${f.label}: ${c.raw.none.includes(f.id)?'Not available from these records':get(c.raw.fields,f.id)} ${get(c.source.units,f.unit,f.unit)}`)),c.feedback];}
function compactWords(r){return r&&typeof r==='object'&&typeof r.feedback==='string'?[r.context?.prompt||'',r.context?.context||'',r.feedback]:[];}
function keptWords(k){if(!C.validLedgerKeep(k))return [];const plan=list(k.source.plans).find(p=>p&&p.id===k.planId);return [k.planId?(plan?`Original provisional plan. ${plan.title}. ${plan.text}`:'Original provisional plan cannot be read here.'):'Provisional plan left open for now.',...k.renderedParts.flatMap(x=>[x.title,x.text||'Left open']),...k.responses.flatMap(r=>r&&typeof r==='object'?[...(r.latestUnreadable?['Latest response cannot be read here.']:compactWords(r.latest)),...compactWords(r.first)]:[]),...k.claims.flatMap(c=>c&&typeof c.reply==='string'?[c.reply]:[])];}
function narration(w,page,state){if(page.role==='note'){const revision=revisionNarration(w,state);if(revision!==null)return revision;}const s=w.source,r=s.records,l=get(w.learn,page.id),target=page.guidedFor,eligible=!target||target.kind==='task'&&get(w.tasks,page.id)===target.id||target.kind==='claim'&&w.claimId===target.id||target.kind==='part'&&w.partId===target.id,words=[page.title];if(C.validLedgerLearn(l,page)&&!l.folded){words.push(...page.learn.slice(0,l.count).map(x=>x.text));if(l.guided&&eligible)words.push(...page.guided.map(x=>x.text));if(page.role==='records'&&C.validLedgerModel(s.model)){const stage=s.model.stages.find(x=>x.id===w.modelStage);if(stage)words.push(s.model.title,stage.text,...stage.counts.map(n=>`${n} times ${s.model.unitValue} ${s.model.unit} equals ${n*s.model.unitValue} ${s.model.unit}`),`${stage.counts.reduce((a,b)=>a+b,0)} blocks total. ${stage.counts.length} stacks.`,s.model.limit);}}
 const ids=[`together-${page.id}`];if(page.role==='records'){words.push(s.labels.ordinary,...r.events.map(e=>`${s.labels.year} ${e.year}: ${e.height} ${s.units.cm}`),r.changeText,r.selectionNote,r.limit);if(w.showStorm)words.push(r.storm.label,r.storm.limit);}if(page.role==='rain'){const sums=C.summarizeLedger(s);words.push(...sums.intervals.map(i=>`${s.labels.year} ${i.label}: ${i.rainCount} recorded big-rain events. ${i.count} ${s.labels.entries}. Maximum ${i.max===null?s.labels.unavailable:`${i.max} ${s.units.cm}`}.`),r.limit);}
 if(['records','rain'].includes(page.role)){const t=s.tasks.find(t=>t.id===get(w.tasks,page.id));if(t){words.push(t.prompt,t.context,...(t.kind==='choice'?t.choices.map(c=>c.text):t.fields.map(f=>`${f.label}, ${get(s.units,f.unit,f.unit)}`)));ids.push(t.hintId,t.exampleId,t.skipId);const latest=w.checks.filter(c=>c&&typeof c==='object'&&own(c,'taskId')&&c.taskId===t.id).at(-1);words.push(...checkWords(latest),...checkWords(get(w.firstChecks,t.id)));}}
 if(page.role==='claims'){const c=s.claims.find(c=>c.id===w.claimId);if(c){words.push(c.text,...s.trays.map(t=>t.label));ids.push(c.hintId,c.exampleId,'claim-skip');const latest=w.claimHistory.filter(x=>x&&typeof x==='object'&&own(x,'cardId')&&x.cardId===c.id).at(-1);if(C.validLedgerClaim(latest))words.push(latest.reply);}}
 if(page.role==='note'){const revision=C.revisionLedgerView(w);if(revision.status==='ready')words.push(revision.revision.source.cards.find(c=>c.id===revision.revision.currentId).question);const part=s.parts.find(p=>p.id===w.partId),plan=s.plans.find(p=>p.id===w.planId);if(plan)words.push(plan.title,plan.text);if(part){words.push(part.title,part.prompt);if(!w.planId&&part.openHelp)words.push(part.openHelp);const raw=get(w.writing,part.id);if(C.validLedgerPart(raw)&&(raw.choiceId===''||part.options.some(o=>o.id===raw.choiceId))){const option=part.options.find(o=>o.id===raw.choiceId);if(option)words.push(option.text);words.push(raw.own);}ids.push(part.helpId);}words.push(...keptWords(get(w,'kept')),...keptWords(get(w,'firstKept')));}
 for(const id of ids)if(w.help.includes(id)&&own(s.help,id))words.push(s.help[id].title,s.help[id].text);return words.filter(x=>typeof x==='string'&&x.length).join('\n\n');}
function sources(w){return `<details class="ledger-sources" data-ledger-panel="sources"><summary>Source drawer · fictional records</summary>${p(w.source.notice)}${p(w.source.drawerIntroduction)}${sourceTables(w)}${w.source.sources.map(s=>`<section><h3>${esc(s.title)}</h3>${p(s.label)}${helpButton(w,`source-${s.id}`,'Open source')}${helpers(w,[`source-${s.id}`])}${!own(w.source.help,`source-${s.id}`)?p(s.text):''}${p(s.reference)}</section>`).join('')}</details>`;}
export const ledgerEntry=()=>'<p class="ledger-entry"><a href="#learn/science/ledger">The ledger and the rain gauge</a> · compare fictional flood records and keep a local evidence note.</p>';
export const ledgerRefusal=()=>'<section class="ledger-page"><h1>The ledger and the rain gauge</h1><h2>Earlier work is safe</h2><p>Newly shown support could not be kept safely. Download your notebook before making room.</p><a href="#notes">Open notes and download</a><a href="#desk">Back to the Desk</a><p id="ledger-status" role="status" tabindex="-1"></p></section>';
export function ledgerPage(state){const v=C.ledgerView(state),w=v.work,s=w?.source||C.createLedgerSource(),status=`<p id="ledger-status" role="status" aria-live="polite" tabindex="-1"></p><div data-ledger-pending-actions hidden><p>Your visible words have not been saved. Copy or edit the marked fields, or restore saved words.</p>${btn('data-ledger-restore','Restore saved words')}</div>`,head=`<div class="ledger-page" data-ledger-root><header><a href="#desk">Back to the Desk</a><h1>${esc(s.title)}</h1></header>`,foot=`${status}<footer><a href="#pathways/science">Science starting points</a><a href="#pathways/math">Math starting points</a><a href="#notes">Notes and download</a></footer></div>`;if(v.status==='unavailable')return head+retained('Earlier case format')+foot;if(!w)return head+`<h2 id="ledger-heading" tabindex="-1">A look at later story records</h2>${p(s.preview)}${p(s.story)}${v.status==='unreadable'?retained('Selected visit'):''}${btn('data-ledger-start','Open the case')}${visits(v)}`+foot;const page=s.pages.find(p=>p.id===w.pageId),audio=`audio-${page.id}`,together=`together-${page.id}`;return head+`<p class="ledger-notice">${esc(s.notice)}</p><nav class="ledger-pages" aria-label="Open parts">${s.pages.map(p=>btn(`data-ledger-page="${esc(p.id)}" aria-current="${p.id===page.id?'page':'false'}"`,p.title)).join('')}</nav><h2 id="ledger-heading" tabindex="-1">${esc(page.title)}</h2>${own(s.help,audio)?hearButton(narration(w,page,state),page.role==='note'?revisionHearLabel(w,state):'Hear this page').replace('data-speak-lang=',`data-ledger-audio="${esc(audio)}" data-speak-lang=`):''}${helpButton(w,together,'Think together')}${helpers(w,[together])}${page.role==='records'?ledgerPlot(w):page.role==='rain'?rainTable(w):''}${teaching(w,page)}${['records','rain'].includes(page.role)?task(w,page):page.role==='claims'?claims(w):note(w,state)}${sources(w)}${visits(v)}`+foot;}
export function ledgerNotes(state){if(!own(state,'ledgerGauge'))return '';const v=C.ledgerView(state);return `<details class="panel ledger-notes"><summary>The ledger and the rain gauge · local fictional case</summary><p>Frozen sources, supported responses, ungraded claims, both writing drafts and first/latest notes stay separate.</p>${v.status==='unavailable'?retained('Earlier format'):v.visits.map(x=>p(`${x.title} · ${x.readable?'retained visit':'unreadable, retained exactly'}`)).join('')}<details><summary>Exact saved case</summary><pre>${esc(JSON.stringify(state.ledgerGauge,null,2))}</pre></details></details>`;}
let removeGuards=()=>{},pendingNavigation=()=>false;
export const guardLedgerNavigation=()=>pendingNavigation();
export function bindLedger(state,{save,render,focus,canExport,exposeFacts,explorerId,isActive}={}){
 removeGuards();removeGuards=()=>{};const root=document.querySelector('[data-ledger-root]');if(!root)return;
 const owner=explorerId?.(),visit=state.ledgerGauge?.current,route=location.hash,o={canExport,exposeFacts},dirty=new Set(),savedValues=new Map([...root.querySelectorAll('[data-ledger-draft]')].map(el=>[el,el.value]));
 const live=el=>root.isConnected&&el?.isConnected&&root.contains(el)&&document.querySelector('[data-ledger-root]')===root&&location.hash===route&&state.ledgerGauge?.current===visit&&explorerId?.()===owner&&(!isActive||isActive());
 const say=(text,take=false)=>{if(!live(root))return;const el=root.querySelector('#ledger-status');if(el){el.textContent=text;if(take)el.focus();}};
 const message='Your visible words have not been saved. Copy or edit the marked fields, or choose Restore saved words before continuing.';
 const pendingUI=()=>{const el=root.querySelector('[data-ledger-pending-actions]');if(el)el.hidden=!dirty.size;};
 const redraw=(text='',target='#ledger-heading',persist=true)=>{const panels=new Map([...root.querySelectorAll('details[data-ledger-panel]')].map(n=>[n.dataset.ledgerPanel,n.open]));stopSpeech();if(persist)save?.();render?.();const next=document.querySelector('[data-ledger-root]');next?.querySelectorAll('details[data-ledger-panel]').forEach(n=>{if(panels.has(n.dataset.ledgerPanel))n.open=panels.get(n.dataset.ledgerPanel);});const status=next?.querySelector('#ledger-status');if(status)status.textContent=text;const node=next?.querySelector(target);if(node){node.focus();if(document.activeElement!==node)focus?.(target);}else focus?.('#ledger-heading');};
 const fail=()=>say('This change could not be kept safely. Earlier saved work stays unchanged. Download your notes before making room.',true);
 const act=(el,fn,text='',target='#ledger-heading')=>{if(!live(el))return false;if(dirty.size){say(message,true);return false;}const r=fn();if(!r){fail();return false;}if(r.recorded===false){say(r.feedback,true);return false;}redraw(text,target);return true;};
 const work=()=>C.ledgerView(state).work;
 const on=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 on('[data-ledger-start]',el=>act(el,()=>C.startLedger(state,o),'Case open. Choose any part.'));
 on('[data-ledger-resume]',el=>act(el,()=>C.resumeLedger(state,el.dataset.ledgerResume,o),'Original source and work resumed.'));
 on('[data-ledger-page]',el=>act(el,()=>C.pageLedger(state,el.dataset.ledgerPage,o)));
 on('[data-ledger-learn]',el=>act(el,()=>C.learnLedger(state,work().pageId,el.dataset.ledgerLearn,o)));
 on('[data-ledger-fold]',el=>act(el,()=>C.foldLedger(state,work().pageId,el.dataset.ledgerFold==='true',o)));
 on('[data-ledger-model]',el=>act(el,()=>C.modelLedger(state,el.dataset.ledgerModel,o),'Supplied example moved.','[data-ledger-model="next"]'));
 on('[data-ledger-storm]',el=>act(el,()=>C.stormLedger(state,el.dataset.ledgerStorm==='true',o)));
 on('[data-ledger-help]',el=>act(el,()=>C.helpLedger(state,el.dataset.ledgerHelp,o),'Requested support kept before reveal.',`[data-ledger-help="${el.dataset.ledgerHelp}"]`));
 on('[data-ledger-check]',el=>act(el,()=>C.checkLedger(state,el.dataset.ledgerCheck,o),'Original response kept.','#ledger-result'));
 on('[data-ledger-skip]',el=>act(el,()=>C.skipLedger(state,el.dataset.ledgerSkip,o),'Question left open.','#ledger-question'));
 on('[data-ledger-tray]',el=>act(el,()=>C.assignLedger(state,el.dataset.card,el.dataset.ledgerTray,o),'Tray reply kept. No score.','#ledger-question'));
 on('[data-ledger-mode]',el=>act(el,()=>C.writingLedger(state,el.dataset.part,'mode',el.dataset.ledgerMode,o),'Both versions remain available.','#ledger-question'));
 on('[data-ledger-starter]',el=>{if(dirty.size)return say(message,true);const id=el.dataset.ledgerStarter,d=get(work()?.writing,id,{}),confirmed=typeof d.own==='string'&&d.own.length?window.confirm('Replace this part’s nonempty own-writing draft with the selected supplied words? Cancel keeps both drafts unchanged.'):false;if(d.own?.length&&!confirmed)return;act(el,()=>C.starterLedger(state,id,confirmed,o),'Supplied starter copied into your writing draft.',`#ledger-own-${id}`);});
 on('[data-ledger-keep]',el=>act(el,()=>C.keepLedgerNote(state,o),work()?.source.keepConfirmation||'Case note kept.','#ledger-note-result'));
 on('[data-ledger-revision-start]',el=>act(el,()=>{const r=C.startLedgerRevision(state,o);if(r)revisionLocal(state,work()).panel='reader';return r;},'Earlier draft kept. Try a reader’s question.','#ledger-reader-heading'));
 on('[data-ledger-reader]',el=>{if(dirty.size)return say(message,true);const view=C.revisionLedgerView(work());if(view.status==='ready'&&view.revision.currentId===el.dataset.ledgerReader)return redraw('This reader’s question is already open.','#ledger-reader-heading',false);act(el,()=>C.readerLedgerRevision(state,el.dataset.ledgerReader,o),'Reader’s question open.','#ledger-reader-heading');});
 on('[data-ledger-revision-keep]',el=>act(el,()=>{const r=C.keepLedgerRevision(state,o);if(r)revisionLocal(state,work()).panel='compare';return r;},'Your revision is kept beside the earlier draft. Keeping it does not say the argument is finished.','#ledger-revision-heading'));
 on('[data-ledger-revision-tab]',el=>{if(dirty.size)return say(message,true);const view=C.revisionLedgerView(work()),panel=el.dataset.ledgerRevisionTab;if(view.status!=='ready'||!['draft','reader','compare'].includes(panel))return;const local=revisionLocal(state,work()),previous=local.panel;local.panel=panel;const display=C.prepareLedgerDisplay(state,o);if(!display.ok){local.panel=previous;fail();return;}redraw('',panel==='draft'?'#ledger-question':panel==='reader'?'#ledger-reader-heading':'#ledger-revision-heading',display.changed);});
 root.querySelectorAll('[data-ledger-revision-part]').forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const view=C.revisionLedgerView(work()),v=revisionLocal(state,work());if(dirty.size){el.value=v.part;say(message,true);return;}if(view.status!=='ready'||!revisionParts(view.revision,view.afterReadable).some(p=>p.id===el.value))return;v.part=el.value;redraw('','#ledger-revision-heading',false);}));
 on('[data-ledger-remove]',el=>{if(dirty.size)return say(message,true);const id=root.querySelector('[data-ledger-remove-choice]')?.value;if(!id)return say('Choose one visit to remove.',true);if(!window.confirm('Remove only this visit, including its frozen sources, drafts and checks? Download notes first if you want a copy.'))return;act(el,()=>C.removeLedgerVisit(state,id,true,o),'Selected visit removed.');});
 const select=(selector,fn,stored,target='#ledger-question',notice='Selection kept.')=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const old=stored(el);if(dirty.size){el.value=old;say(message,true);return;}if(!act(el,()=>fn(el),typeof notice==='function'?notice(el):notice,typeof target==='function'?target():target))el.value=old;}));
 for(const type of ['task','claim','part']){const choose=id=>type==='task'?C.taskLedger(state,work().pageId,id,o):type==='claim'?C.claimLedger(state,id,o):C.partLedger(state,id,o),target=()=>type==='part'&&C.revisionLedgerView(work()).status==='ready'&&revisionLocal(state,work()).panel==='reader'?'[data-ledger-part]':'#ledger-question',notice=id=>type==='part'?'Writing part: '+(work().source.parts.find(p=>p.id===id)?.title||'Left open'):'Selection kept.';select(`[data-ledger-${type}]`,el=>choose(el.value),()=>type==='task'?get(work()?.tasks,work()?.pageId):type==='claim'?work()?.claimId:work()?.partId,target,el=>notice(el.value));on(`[data-ledger-${type}-go]`,el=>{const id=el.getAttribute(`data-ledger-${type}-go`);act(el,()=>choose(id),type==='part'?notice(id):'',target());});}
 select('[data-ledger-answer]',el=>C.choiceLedger(state,el.dataset.ledgerAnswer,el.value,o),el=>get(get(work()?.answers,el.dataset.ledgerAnswer,{}),'choiceId'));
 select('[data-ledger-plan]',el=>C.planLedger(state,el.value,o),()=>work()?.planId);
 select('[data-ledger-writing-choice]',el=>C.writingLedger(state,el.dataset.ledgerWritingChoice,'choiceId',el.value,o),el=>get(get(work()?.writing,el.dataset.ledgerWritingChoice,{}),'choiceId'));
 root.querySelectorAll('[data-ledger-none]').forEach(el=>el.addEventListener('change',()=>{if(!live(el))return;const old=list(get(work()?.answers,el.dataset.task,{}).none).includes(el.dataset.ledgerNone);if(!act(el,()=>C.noneLedger(state,el.dataset.task,el.dataset.ledgerNone,el.checked,o),'Response kept.','#ledger-question'))el.checked=old;}));
 const input=(el,fn)=>el.addEventListener('input',()=>{if(!live(el))return;if(!fn(el.value)){dirty.add(el);el.setAttribute('aria-invalid','true');pendingUI();say(message);return;}savedValues.set(el,el.value);dirty.delete(el);el.removeAttribute('aria-invalid');save?.();pendingUI();say(dirty.size?message:'Words saved.');});
 root.querySelectorAll('[data-ledger-field]').forEach(el=>input(el,raw=>C.answerLedger(state,el.dataset.task,el.dataset.ledgerField,raw,o)));
 root.querySelectorAll('[data-ledger-own]').forEach(el=>input(el,raw=>C.writingLedger(state,el.dataset.ledgerOwn,'own',raw,o)));
 on('[data-ledger-restore]',el=>{if(!live(el)||!window.confirm('Discard visible unsaved edits and restore the last saved words?'))return;for(const field of dirty){field.value=savedValues.get(field)??'';field.removeAttribute('aria-invalid');}dirty.clear();pendingUI();say('Last saved words restored.',true);});
 // This capture listener runs before shared speech: support is saved before any playback.
 root.addEventListener('click',e=>{const el=e.target.closest?.('[data-speak]');if(!el)return;const code=el.dataset.ledgerAudio;if(!live(el)||dirty.size||!code){e.preventDefault();e.stopImmediatePropagation();if(dirty.size)say(message,true);return;}if(!C.helpLedger(state,code,o)){e.preventDefault();e.stopImmediatePropagation();fail();return;}const current=work(),page=current.source.pages.find(p=>p.id===current.pageId);el.dataset.speak=narration(current,page,state);save?.();},true);
 const guard=e=>{if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;if(!live(root)||!dirty.size)return;const target=e.target;if(target?.closest?.('[data-ledger-draft],[data-ledger-restore]'))return;if(target?.closest?.('button,a,input,select,summary')){e.preventDefault();e.stopImmediatePropagation();say(message,true);}};
 pendingNavigation=()=>{if(!root.isConnected||document.querySelector('[data-ledger-root]')!==root||explorerId?.()!==owner||!dirty.size)return false;window.history.replaceState(null,'',route);stopSpeech();const status=root.querySelector('#ledger-status');if(status){status.textContent=message;status.focus();}return true;};
 const beforeLeave=e=>{if(dirty.size&&live(root)){e.preventDefault();e.returnValue='';}};
 document.addEventListener('click',guard,true);document.addEventListener('keydown',guard,true);window.addEventListener('beforeunload',beforeLeave);
 removeGuards=()=>{document.removeEventListener('click',guard,true);document.removeEventListener('keydown',guard,true);window.removeEventListener('beforeunload',beforeLeave);pendingNavigation=()=>false;};
}
